// Names extracted from Hassan Heshmat's autobiography for the Memoir page.
// memoir.json is generated by docs/autobiography/build_site_data.py; do not
// edit it by hand — the README there describes the whole pipeline.
import data from './memoir.json';

export type MemoirType = 'person' | 'place' | 'organisation' | 'artwork' | 'exhibition';
export type PlaceLevel = 'country' | 'region' | 'city' | 'district' | 'street' | 'site';

export interface MemoirEntity {
	id: string;
	type: MemoirType;
	/** English or established Latin form, normalised by the model. */
	name: string;
	nameAr: string;
	/** How often the book names it. */
	mentions: number;
	/** Printed pages of the book. */
	pages: number[];
	/** People only. */
	description?: string;
	/** A site record ("artwork:3", "residence:4", "person:<slug>"). */
	record?: string;
	years?: number[];
	level?: PlaceLevel;
	lat?: number;
	lng?: number;
	/** OpenStreetMap object the coordinates come from ("relation/123"). */
	osm?: string;
}

export const memoirBook = data.book;
export const memoirMethod = data.method;
export const memoirCounts = data.counts as Record<MemoirType, number>;
export const memoirEntities = data.entities as MemoirEntity[];

/** Levels drawn as points; countries and regions are listed instead. */
export const MAPPED_LEVELS: ReadonlySet<PlaceLevel> = new Set([
	'city',
	'district',
	'street',
	'site'
]);

export function ofType(type: MemoirType): MemoirEntity[] {
	return memoirEntities.filter((entity) => entity.type === type);
}

/** "p. 7", "pp. 7, 9, 12", "pp. 7, 9, 12, 14, 18 and 6 more". */
export function pageLabel(pages: number[], shown = 5): string {
	if (!pages.length) return '';
	const head = pages.slice(0, shown).join(', ');
	const rest = pages.length - shown;
	return `${pages.length === 1 ? 'p.' : 'pp.'} ${head}${rest > 0 ? ` and ${rest} more` : ''}`;
}
